#!/usr/bin/env python3
import json, re

RE = "/home/researcher/work/csaw/submission/re"

# --- parse the real ROM word table W (128 x 16b) from clean_model.v ---
txt = open(f"{RE}/clean_model.v").read()
# grab the first memory's initial assignments
W = {}
for m in re.finditer(r"\.memory \[(\d+)\] = 16'h([0-9a-fA-F]+);", txt):
    a = int(m.group(1)); v = int(m.group(2),16)
    if a not in W:            # first RAM block wins
        W[a] = v
    if len(W) >= 128 and a < len(W):
        pass
Wtab = [W[a] for a in range(128)]
print("ROM words[0..7]:", [hex(x) for x in Wtab[:8]])

# --- ground-truth lane maps ---
E = json.load(open(f"{RE}/E.json"))
Elane = {}
for k, tbl in E.items():
    arr=[0]*256
    for i,v in tbl.items(): arr[int(i)]=v
    Elane[int(k)]=arr

def make_S(hi_when_lsb1):
    S=[0]*256
    for x in range(256):
        w=Wtab[x>>1]
        lo=w&0xff; hi=(w>>8)&0xff
        if (x&1)==1:
            S[x]= hi if hi_when_lsb1 else lo
        else:
            S[x]= lo if hi_when_lsb1 else hi
    return S

for hi1 in (True,False):
    S=make_S(hi1)
    bij = sorted(S)==list(range(256))
    print(f"\n=== S-box (hi_byte_when_lsb1={hi1}) bijection={bij} ===")
    Sinv=[0]*256
    if bij:
        for x in range(256): Sinv[S[x]]=x
    # Hypothesis 1: E_i(p) = S(p ^ k)
    for lane in range(4):
        hits=[]
        for k in range(256):
            if all(S[p^k]==Elane[lane][p] for p in range(256)):
                hits.append(k)
        print(f" lane{lane} E=S(p^k):            k={[hex(x) for x in hits]}")
    # Hypothesis 2: E_i(p) = S(p ^ k) ^ c   (input + output whitening, XOR)
    for lane in range(4):
        found=[]
        for k in range(256):
            c=S[0^k]^Elane[lane][0]
            if all(S[p^k]^c==Elane[lane][p] for p in range(256)):
                found.append((k,c))
        print(f" lane{lane} E=S(p^k)^c:          {[(hex(a),hex(b)) for a,b in found]}")
    # Hypothesis 3: E_i(p) = S^{-1}(p) type / Sinv(p^k)
    if bij:
        for lane in range(4):
            hits=[]
            for k in range(256):
                if all(Sinv[p^k]==Elane[lane][p] for p in range(256)):
                    hits.append(k)
            if hits: print(f" lane{lane} E=Sinv(p^k):         k={[hex(x) for x in hits]}")
    # Hypothesis 4: E_i(p) = S(p)^k  (output XOR only, no input key)
    for lane in range(4):
        if len(set(S[p]^Elane[lane][p] for p in range(256)))==1:
            print(f" lane{lane} E=S(p)^k:  k={hex(S[0]^Elane[lane][0])}")

