#!/usr/bin/env python3
import json
RE="/home/researcher/work/csaw/submission/re"
E=json.load(open(f"{RE}/E.json"))
L={}
for k,t in E.items():
    a=[0]*256
    for i,v in t.items(): a[int(i)]=v
    L[int(k)]=a

off={0:0x58,1:0x1e,2:0x02,3:0x47}   # = k_i>>1 measured

# Test E_i(p) = E_j(p ^ a) ^ b  for every ordered pair -> recover relative key a=k_i^k_j
print("Pairwise affine-XOR relation  E_i(p)=E_j(p^a)^b :")
rel={}
for i in range(4):
    for j in range(4):
        if i==j: continue
        sols=[]
        for a in range(256):
            b=L[i][0]^L[j][0^a]
            if all(L[i][p]^b==L[j][p^a] for p in range(256)):
                sols.append((a,b))
        if sols:
            rel[(i,j)]=sols
            print(f"  E{i}(p)=E{j}(p^a)^b : {[(hex(a),hex(b)) for a,b in sols]}")
if not rel:
    print("  (none) -> lanes are not pure XOR-translates")

# If input-only whitening (b==0) relative keys recovered:
print("\nRelative input keys a=k_i^k_j where b==0:")
for (i,j),sols in rel.items():
    for a,b in sols:
        if b==0:
            print(f"  k{i}^k{j} = {hex(a)}  (consistent with off diff {hex(off[i]^off[j])}<<1 ? "
                  f"{(a>>1)==(off[i]^off[j])})")

